const set=data.settings||{};
const appts=data.appointments.filter((a:Row)=>{const dt=new Date(a.starts_at).toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'});const diff=(new Date(dt+'T12:00').getTime()-new Date(day+'T12:00').getTime())/86400000;return(view==='Dia'?dt===day:view==='Semana'?diff>=0&&diff<7:dt.slice(0,7)===day.slice(0,7))&&(!prof||a.professional_id===prof)}).sort((a:Row,b:Row)=>a.starts_at.localeCompare(b.starts_at));
