{modal==='professional'&&<><Field label="Nome completo" name="name" form={form} set={F} required/><Field label="WhatsApp" name="phone" type="tel" form={form} set={F}/><label>Foto (PNG ou JPEG, até 2 MB)<input type="file" accept="image/png,image/jpeg" onChange={async e=>{if(!e.target.files?.[0])return;try{if(demo){notify('Uploads ficam disponíveis no ambiente real.');return;}const fd=new FormData();fd.set('file',e.target.files[0]);fd.set('tenant',data.tenant.id);const r=await fetch('/api/upload',{method:'POST',body:fd});const x:any=await r.json();if(x.error)throw Error(x.error);F({...form,photo:x.url})}catch(e:any){notify(e.message)}}}/></label>{form.photo&&<Avatar name={form.name} photo={form.photo}/>}<label>Serviços habilitados</label><div className="checks">{data.services.map((s:Row)=><label className="check" key={s.id}><input type="checkbox" checked={form.service_ids?.includes(s.id)} onChange={e=>F({...form,service_ids:e.target.checked?[...form.service_ids,s.id]:form.service_ids.filter((id:string)=>id!==s.id)})}/>{s.emoji} {s.name}</label>)}</div><p className="tiny">Sem expediente próprio, será usado o horário do estabelecimento.</p><Schedule cfg={form.schedule||{}} set={(schedule:Row)=>F({...form,schedule})}/><label className="check"><input type="checkbox" checked={form.active} onChange={e=>F({...form,active:e.target.checked})}/>Profissional ativo</label></>}
{modal==='appointment'&&<><Field label="Profissional" name="professional_id" options={data.professionals.filter((p:Row)=>p.active).map((p:Row)=>({value:p.id,label:p.name}))} form={form} set={F} required/>{form.status!=='Bloqueado'&&<><Field label="Cliente" name="customer_id" options={data.customers.map((p:Row)=>({value:p.id,label:p.name}))} form={form} set={F} required/><button type="button" className="textbutton" onClick={()=>edit('customer')}>＋ Cadastrar cliente primeiro</button><Field label="Procedimento" name="service_id" options={data.services.filter((s:Row)=>s.active).map((p:Row)=>({value:p.id,label:p.name}))} form={form} set={F} required/></>}{form.status!=='Bloqueado'&&<Field label="Forma de pagamento" name="payment_method" options={paymentMethods} form={form} set={F} required/>}<Field label="Início" name="starts_at" type="datetime-local" form={form} set={F} required/>{form.status==='Bloqueado'&&<Field label="Fim" name="ends_at" type="datetime-local" form={form} set={F} required/>}<p className="tiny">Horários no fuso de Brasília. A disponibilidade será validada ao salvar.</p></>}
