function Empty({icon,title,text}:any){return <div className="empty"><span>{icon}</span><h3>{title}</h3><p>{text}</p></div>}
function Schedule({cfg,set}:any){return <><div className="days">{['D','S','T','Q','Q','S','S'].map((d,i)=><button key={i} type="button" title={['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'][i]} className={(cfg.days||[1,2,3,4,5,6]).includes(i)?'on':''} onClick={()=>set({...cfg,days:(cfg.days||[1,2,3,4,5,6]).includes(i)?(cfg.days||[1,2,3,4,5,6]).filter((x:number)=>x!==i):[...(cfg.days||[1,2,3,4,5,6]),i]})}>{d}</button>)}</div><div className="formgrid"><Field label="Abertura" name="opening" type="time" form={cfg} set={set}/><Field label="Fechamento" name="closing" type="time" form={cfg} set={set}/><Field label="Início do intervalo" name="break_start" type="time" form={cfg} set={set}/><Field label="Fim do intervalo" name="break_end" type="time" form={cfg} set={set}/></div></>}
function Settings({data,save,notify,demo,busy}:any){const [cfg,C]=useState<Row>(data.settings);const [section,S]=useState('Estabelecimento');const [password,P]=useState('');const [member,M]=useState<Row>({role:'professional',email:'',professional_id:''});return <div className="settingslayout"><nav className="settingsnav">{['Estabelecimento','Aparência','Redes sociais','Funcionamento','Notificações','Acessos'].map((s,i)=><button className={section===s?'selected':''} key={s} onClick={()=>S(s)}>{['🏪','🎨','📲','🕒','🔔','🔐'][i]} {s}</button>)}</nav><section className="panel settingspanel" style={neonTheme(cfg.palette,cfg.accent)}><h2>{section}</h2><p>Personalize a experiência do seu estabelecimento.</p><form onSubmit={e=>{e.preventDefault();if((cfg.break_start&&!cfg.break_end)||(!cfg.break_start&&cfg.break_end)){notify('Informe o início e o fim do intervalo.');return;}save('settings',{data:cfg})}}>
{section==='Estabelecimento'&&<div className="formgrid">{[['Nome exibido','display_name'],['Razão social','legal_name'],['CNPJ','cnpj'],['Endereço completo','address'],['Cidade','city'],['Estado','state'],['CEP','cep'],['Telefone','phone'],['WhatsApp com DDD','whatsapp'],['E-mail','email'],['Mensagem de boas-vindas','welcome']].map(([label,name])=><Field key={name} label={label} name={name} form={cfg} set={C}/>)}</div>}
{section==='Redes sociais'&&<>{[['Instagram (URL completa)','instagram'],['Facebook (URL completa)','facebook'],['WhatsApp (com DDD)','whatsapp']].map(([label,name])=><Field key={name} label={label} name={name} form={cfg} set={C}/>)}</>}
{section==='Notificações'&&<PushControl tenantId={data.tenant.id} demo={demo} notify={notify}/>}{section==='Aparência'&&<><div className="logopreview">{cfg.logo?<img src={cfg.logo} alt="Logo do estabelecimento"/>:<span>💈</span>}<div><strong>Logo do estabelecimento</strong><p>PNG ou JPEG · até 2 MB</p><input aria-label="Enviar logo" type="file" accept="image/png,image/jpeg" onChange={async e=>{if(!e.target.files?.[0])return;if(demo){notify('Envio de arquivos disponível no ambiente real.');return;}const fd=new FormData();fd.set('tenant',data.tenant.id);fd.set('file',e.target.files[0]);try{const r=await fetch('/api/upload',{method:'POST',body:fd});const d:any=await r.json();if(d.error)throw Error(d.error);C({...cfg,logo:d.url});}catch(e:any){notify(e.message)}}}/>{cfg.logo&&<button className="textbutton" type="button" onClick={()=>C({...cfg,logo:''})}>Remover logo</button>}</div></div><h3>Sua identidade, em neon ✨</h3><p>Escolha uma paleta. O brilho acompanha sua cor e mantém a leitura confortável.</p><div className="palettes">{Object.entries(palettes).map(([key,p])=><button key={key} type="button" style={neonTheme(key)} aria-pressed={cfg.palette===key} className={'palette '+(cfg.palette===key?'selected':'')} onClick={()=>C({...cfg,palette:key,accent:''})}><span className="swatches">{p.slice(1).map((c:string)=><i key={c} style={{background:c}}/>)}</span>{p[0]}{cfg.palette===key&&' ✓'}</button>)}</div><div className="neon-preview"><span className="eyebrow">PRÉVIA DA SUA PALETA</span><h3>Seu próximo horário, em destaque.</h3><p>💈 Corte masculino <span>30 min</span></p><button type="button" className="primary" onClick={()=>notify('Prévia da paleta selecionada. Salve as configurações para aplicar ao estabelecimento.')}>✨ Agendar meu horário →</button></div><label>Cor de destaque personalizada<input type="color" value={cfg.accent||palettes[cfg.palette||'black'][1]} onChange={e=>C({...cfg,accent:e.target.value})}/></label><p className="tiny">O texto dos botões usa contraste calculado automaticamente.</p></>}
{section==='Funcionamento'&&<><Schedule cfg={cfg} set={C}/><div className="formgrid"><Field label="Antecedência mínima (min)" name="min_notice" type="number" form={cfg} set={C}/><Field label="Agendar até quantos dias à frente" name="max_days" type="number" form={cfg} set={C}/><Field label="Intervalo entre opções (min)" name="interval" type="number" form={cfg} set={C}/></div><label>Feriados / datas sem atendimento (AAAA-MM-DD, um por linha)<textarea value={(cfg.holidays||[]).join('\n')} onChange={e=>C({...cfg,holidays:e.target.value.split('\n').filter(Boolean)})}/></label><label>Política de cancelamento<textarea value={cfg.cancellation_policy||''} onChange={e=>C({...cfg,cancellation_policy:e.target.value})}/></label></>}
{!['Acessos','Notificações'].includes(section)&&<button className="primary" disabled={busy}>✓ Salvar configurações</button>}</form>
{section==='Acessos'&&<><h3>Alterar minha senha</h3><Password label="Nova senha (mínimo 10 caracteres)" value={password} onChange={P}/><button className="primary" onClick={()=>demo?notify('Alteração disponível no ambiente real.'):auth({action:'password',password}).then(d=>{notify(d.message);P('')}).catch(e=>notify(e.message))}>Atualizar senha</button><hr/><h3>Usuários autorizados</h3><p className="tiny">O usuário cria sua senha na tela de acesso e confirma o mesmo e-mail cadastrado abaixo.</p>{data.memberships.map((m:Row)=><div className="historyrow" key={m.id}><strong>{m.email}</strong><span>{m.role==='admin'?'Administrador':'Profissional'} · {m.active?'Ativo':'Desativado'}</span><button className="textbutton" onClick={()=>{if(confirm(m.active?'Desativar acesso?':'Reativar acesso?'))save('member',{...m,active:!m.active})}}>{m.active?'Desativar':'Reativar'}</button></div>)}<form onSubmit={e=>{e.preventDefault();save('member',member)}}><Field label="E-mail de acesso" type="email" name="email" form={member} set={M} required/><Field label="Permissão" name="role" options={[{value:'admin',label:'Administrador da empresa'},{value:'professional',label:'Profissional — apenas própria agenda'}]} form={member} set={M} required/>{member.role==='professional'&&<Field label="Profissional vinculado" name="professional_id" options={data.professionals.map((p:Row)=>({value:p.id,label:p.name}))} form={member} set={M} required/>}<button className="secondary">＋ Autorizar usuário</button></form></>}
</section></div>}
function CompanyAccessReceipt({access,close,notify}:any){const [show,S]=useState(false);const link=typeof location!=='undefined'?location.origin+'/'+access.slug+'/admin':'/'+access.slug+'/admin';return <Modal title="Acesso da empresa pronto" close={close}><p>✅ A empresa já possui um administrador com acesso por e-mail e senha.</p><label>Link do painel<input value={link} readOnly/></label><label>E-mail de login<input value={access.email} readOnly/></label>{access.password?<label>Senha inicial<span className="password"><input value={access.password} type={show?'text':'password'} readOnly autoComplete="off"/><button type="button" aria-label={show?'Ocultar senha inicial':'Mostrar senha inicial'} onClick={()=>S(!show)}>{show?'🙈':'👁️'}</button></span><small>A senha é exibida somente nesta confirmação. Ela não fica disponível para consulta após fechar.</small></label>:<p className="notice">Este acesso já foi criado em uma tentativa anterior. Utilize a senha definida na primeira tentativa; ela não foi alterada.</p>}<button type="button" className="primary full" onClick={async()=>{try{await navigator.clipboard.writeText('🔐 Acesso ao Agenda+\nPainel: '+link+'\nE-mail: '+access.email+'\nSenha: '+(access.password||'a definida na primeira tentativa')+'\nEntre com e-mail e senha.');notify('Dados de acesso copiados.')}catch{notify('Não foi possível copiar. Consulte os dados exibidos nesta confirmação.')}}}>📋 Copiar dados de acesso</button><button type="button" className="secondary full" onClick={close}>Concluir</button></Modal>}
function PlanShareModal({plans,initialIds,companies,close,notify}:any){const [whatsAppTarget,WT]=useState<'app'|'web'>('app');useEffect(()=>{WT(planWhatsAppTarget(navigator.userAgent,navigator.maxTouchPoints))},[]);const available=availableSharePlans(plans);const [ids,I]=useState<string[]>(initialIds);const [name,N]=useState('');const [phone,P]=useState('');const [company,C]=useState('');const selected=available.filter(p=>ids.includes(p.id));const message=plansWhatsAppMessage(selected,name);const url=message?whatsappUrl(phone,message,whatsAppTarget):'';const chatUrl=whatsappUrl(phone,'',whatsAppTarget);const tooLong=message.length>10000;return <Modal title="Compartilhar planos pelo WhatsApp" close={close}><p>Selecione as opções para o cliente analisar e escolher.</p><fieldset className="plan-share-options"><legend>💳 Planos da proposta</legend><div className="plan-share-select"><button type="button" className="textbutton" onClick={()=>I(available.map(p=>p.id))}>Selecionar todos</button><span>{selected.length} selecionado(s)</span></div>{available.map(p=><label className="plan-share-option" key={p.id}><input type="checkbox" checked={ids.includes(p.id)} onChange={e=>I(e.target.checked?[...ids,p.id]:ids.filter(id=>id!==p.id))}/><span><strong>{p.name}</strong><small>{money(p.amount)} · {planRenewalLabel(p.months)}</small></span></label>)}</fieldset>{companies.length>0&&<label>Usar contato de uma empresa cadastrada (opcional)<select value={company} onChange={e=>{C(e.target.value);const c=companies.find((c:Row)=>c.id===e.target.value);if(c){N(c.responsible||c.name);P(c.phone||'')}}}><option value="">Informar contato manualmente</option>{companies.map((c:Row)=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label>}<div className="formgrid"><label>Nome do cliente (opcional)<input autoComplete="off" maxLength={120} value={name} onChange={e=>N(e.target.value)} placeholder="Como o cliente se chama?"/></label><label>📱 WhatsApp com DDD<input type="tel" inputMode="tel" autoComplete="off" maxLength={30} value={phone} onChange={e=>P(e.target.value)} placeholder="(24) 99999-9999"/><small>Para números do Brasil, informe DDD e telefone.</small></label></div><label>Prévia da mensagem<textarea className="plan-share-preview" rows={14} readOnly value={message} placeholder="Selecione pelo menos um plano."/></label>{!selected.length&&<p className="notice">Selecione pelo menos um plano para compartilhar.</p>}{phone&&!url&&selected.length>0&&<p className="notice">Confira o WhatsApp com DDD ou código do país.</p>}{tooLong&&<p className="notice">A proposta está muito longa para abrir de uma vez. Compartilhe menos planos ou copie a mensagem.</p>}<div className="plan-share-actions">{url&&!tooLong?<a className="primary full" href={url} target="_blank" rel="noopener noreferrer">📲 Abrir WhatsApp com os planos</a>:<button type="button" className="primary full" disabled>📲 Abrir WhatsApp com os planos</button>}<button type="button" className="secondary full" disabled={!message} onClick={async()=>{try{await navigator.clipboard.writeText(message);notify('Mensagem copiada com os emojis. Cole na conversa do WhatsApp.')}catch{notify('Não foi possível copiar automaticamente. Selecione o texto da prévia.')}}}>📋 Copiar mensagem com emojis</button></div><details className="plan-emoji-help"><summary>Emojis diferentes ao abrir o WhatsApp?</summary><p>Use “Copiar mensagem com emojis”, abra a conversa abaixo e cole no campo de mensagem. Assim, o texto não passa pelo link de compartilhamento.</p>{chatUrl?<a className="secondary full" href={chatUrl} target="_blank" rel="noopener noreferrer">💬 Abrir conversa para colar</a>:<p>Informe um WhatsApp válido com DDD para abrir a conversa.</p>}</details><p className="tiny">{whatsAppTarget==='web'?'No computador, a proposta abre diretamente no WhatsApp Web. ':''}O WhatsApp será aberto com a mensagem pronta. Revise o destinatário e confirme o envio por lá. A escolha do cliente será combinada na conversa.</p></Modal>}
