const active=data.tenants.filter((t:Row)=>t.status==='active'&&t.license.expires_on>=today());const soon=data.tenants.filter((t:Row)=>{const days=(new Date(t.license.expires_on).getTime()-Date.now())/86400000;return days>=0&&days<15});
